<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount,nextTick} from 'vue';
import {X,Download,RefreshCw,AlertCircle} from 'lucide-vue-next';
import {api,fetchCsv} from './api';
import {reportHtml,downloadReportBlob,reportNumber,actionLabel,provenanceLabel} from './reportExport';
const props=defineProps<{request:any}>(),emit=defineEmits(['close']);
const dialog=ref<HTMLDialogElement>(),report=ref<any>(null),error=ref(''),busy=ref(false),message=ref('');let alive=true,generation=0,controller:AbortController|undefined,returnFocus:HTMLElement|null=null;
const courseMode=props.request.kind==='course';
async function load(){const g=++generation;busy.value=true;error.value='';message.value='';report.value=null;try{const data=await api(`/progress-entries/${props.request.entryId}/report`);if(!alive||g!==generation)return;if(data.schemaVersion!==1||data.kind!=='ENTRY_PROGRESS_REPORT'||data.entry?.id!==props.request.entryId||data.entry?.course_id!==props.request.courseId||!data.summary||!Array.isArray(data.versions)||!Array.isArray(data.feedback)||!Array.isArray(data.notes))throw Error('报告范围或格式不一致，请重新生成');report.value=data;}catch(e:any){if(alive&&g===generation)error.value=e.message||'报告生成失败';}finally{if(alive&&g===generation)busy.value=false;}}
function readableTime(value:string){const date=new Date(value);return Number.isNaN(date.getTime())?'时间未记录':date.toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false,timeZone:'Asia/Shanghai'})+'（北京时间 UTC+8）';}
function close(){controller?.abort();generation++;dialog.value?.close();emit('close');}
async function csv(){const g=++generation;controller?.abort();controller=new AbortController();busy.value=true;error.value='';message.value='';try{const params=new URLSearchParams(props.request.filters),blob=await fetchCsv(`/courses/${props.request.courseId}/progress-export.csv?${params}`,controller.signal);if(!alive||g!==generation)return;downloadReportBlob(blob,`course-progress-${props.request.courseId}.csv`);message.value='CSV 已交给浏览器下载；包含全部匹配页，不仅是当前页。请安全保存。';}catch(e:any){if(alive&&g===generation&&e.name!=='AbortError')error.value=e.message||'导出失败，请重试';}finally{if(alive&&g===generation)busy.value=false;}}
function download(format:'html'|'json'){if(!report.value||busy.value)return;const data=report.value,body=format==='html'?reportHtml(data):JSON.stringify(data,null,2);downloadReportBlob(new Blob([body],{type:format==='html'?'text/html;charset=utf-8':'application/json;charset=utf-8'}),`entry-${data.entry.id}-progress.${format}`);message.value='已交给浏览器下载。文件是当前报告快照，不会自动同步后续评价。';}
onMounted(async()=>{returnFocus=document.activeElement as HTMLElement;dialog.value?.showModal();await nextTick();if(!courseMode)await load();});
onBeforeUnmount(()=>{alive=false;generation++;controller?.abort();dialog.value?.close();returnFocus?.focus();});
</script>
<template><Teleport to="body"><dialog ref="dialog" class="report-dialog" aria-labelledby="report-heading" @cancel.prevent="close"><header><div><span class="eyebrow">本地下载 · 不自动发布或分享</span><h2 id="report-heading">{{courseMode?'导出进展 CSV':'作品学习报告'}}</h2></div><button class="icon-btn" aria-label="关闭报告导出" @click="close"><X :size="20"/></button></header><div class="report-body" :aria-busy="busy">
 <p class="report-privacy">文件包含个人学习记录与教师反馈。仅用于获授权的课程教学，下载后请自行安全保存；本操作不发布作品、不发送邮件。</p>
 <p v-if="error" role="alert" class="report-error"><AlertCircle :size="17"/>{{error}} <button class="text-btn" :disabled="busy" @click="courseMode?csv():load()">重试生成报告</button></p><p v-if="message" role="status" class="report-message">{{message}}</p><p v-if="busy" role="status">{{courseMode?'正在生成完整筛选范围的 CSV…':'正在读取完整版本与反馈记录…'}}</p>
 <template v-if="courseMode"><h3>当前导出范围</h3><dl class="report-scope"><dt>课程</dt><dd>{{request.courseLabel||request.courseId}}</dd><dt>关键词</dt><dd>{{request.filters.q||'未限定'}}</dd><dt>作业</dt><dd>{{request.assignmentLabel}}</dd><dt>作者</dt><dd>{{request.authorLabel}}</dd><dt>状态</dt><dd>{{request.stateLabel}}</dd><dt>预计匹配作品</dt><dd>{{request.total}} 篇（以生成时记录为准）</dd></dl><p>导出全部匹配页；不受当前翻页位置影响。概览统计按作业、作者、关键词范围计算，不随状态标签改变；CSV 会分别标注概览与导出行数。</p><p>仅含作品索引、版本/评价编号、四维正式分数与反馈数量，不含正文或教师私有评分草稿。未评分保持空白，不记为零分。最多 2000 篇，超限会要求缩小范围，不静默截断。</p><p class="muted">CSV 为 UTF-8（含 BOM）；电子表格公式前缀已中和。显示名称是生成时名称。</p><button class="btn primary" :disabled="busy" @click="csv"><Download :size="16"/>下载当前筛选 CSV</button></template>
 <template v-else-if="report"><div class="report-title"><h3>{{report.entry.title}}</h3><p>{{report.entry.author_name}} · {{report.entry.course_title}} · {{report.entry.assignment_title}}</p><p class="muted">生成时间：<time :datetime="report.generatedAt" :title="report.generatedAt">{{readableTime(report.generatedAt)}}</time> · 作品 #{{report.entry.id}}</p></div><section class="report-summary"><p>累计提交 <strong>{{report.summary.submissions}}</strong> 个版本；其中 {{report.summary.pending_versions}} 个待评。</p><p>最新提交：{{report.summary.latest_submitted_version==null?'尚未提交':'v'+report.summary.latest_submitted_version}}。</p><p>最近已评分：<template v-if="report.summary.latest_graded_version!=null">v{{report.summary.latest_graded_version}} · 评价 r{{report.summary.latest_evaluation_revision}} · <strong>{{reportNumber(report.summary.latest_score)}}</strong> /100</template><template v-else>无正式评价，不计为零分</template>。</p><p>反馈已解决 {{report.summary.resolved_feedback}} / {{report.summary.feedback_total}} 条；未解决 {{report.summary.open_feedback}} 条。采纳不等于解决。</p></section>
 <h3>完整提交版本（{{report.versions.length}}）</h3><p class="muted">每行显示该提交当前生效的正式评价；复评不会新增提交。报告不计算“成长率”或个人排名。</p><article v-for="v in report.versions" :key="v.id" class="report-version"><strong>v{{v.version_no}} · {{v.title}}</strong><p><time :datetime="v.created_at" :title="v.created_at">{{readableTime(v.created_at)}}</time> · <code class="rubric-version-chip" :title="v.rubric_version">{{v.rubric_version}}</code></p><p class="muted">{{provenanceLabel[v.rubric_provenance]||'当时标准状态未知'}}</p><template v-if="v.q_final!=null"><p>{{reportNumber(v.q_final)}} /100 · 评价 r{{v.evaluation_revision}} · {{v.teacher_name}}</p><div class="report-dimensions"><span v-for="[code,label] in [['S','科学性'],['A','准确性'],['C','完整性'],['L','逻辑性']]" :key="code">{{label}} {{reportNumber(v.dimensions?.[code])}}</span></div><p class="report-text">{{v.evaluation_summary}}</p><p v-if="v.gate_reason" class="report-text">教师确认的质量门槛说明：{{v.gate_reason}}</p></template><p v-else>待教师评审，未评分不计零分。</p></article><p v-if="!report.versions.length">仅有草稿，尚无提交版本。</p>
 <h3>教师反馈与处理记录（{{report.feedback.length}}）</h3><article v-for="f in report.feedback" :key="f.id" class="report-feedback"><strong>v{{f.version_no}} · {{f.indicator_code}} · {{f.resolved?'教师已确认解决':'待教师确认解决'}}</strong><p>{{f.teacher_name}} · <time :datetime="f.created_at" :title="f.created_at">{{readableTime(f.created_at)}}</time></p><p class="report-text">{{f.body}}</p><blockquote class="report-text">{{f.original_text}}</blockquote><p v-if="f.author_action">作者最近处理：{{actionLabel[f.author_action]||f.author_action}}{{f.resolved?'':'；仍待教师确认'}}。</p><details v-if="f.actions.length"><summary>处理历史（{{f.actions.length}}）</summary><div v-for="a in f.actions" :key="a.id" class="report-action"><strong>{{a.actor_name}} · {{actionLabel[a.action_type]||a.action_type}}</strong><small><time :datetime="a.created_at" :title="a.created_at">{{readableTime(a.created_at)}}</time></small><p class="report-text">{{a.body}}</p></div></details><p v-else class="muted">暂无处理记录。</p></article><p v-if="!report.feedback.length">尚无教师反馈记录。</p><h3>范围与使用说明</h3><ul><li v-for="note in report.notes" :key="note">{{note}}</li></ul><p class="muted">HTML 是无需联网的可打印文档，可用浏览器打印另存 PDF；本版不自动生成 PDF，不含完整正文或量规锚点，不是档案备份。JSON 保留同一报告数据供复核。</p>
 </template></div><footer><template v-if="!courseMode&&report"><button class="btn secondary" :disabled="busy" @click="load"><RefreshCw :size="15"/>重新生成快照</button><button class="btn secondary" :disabled="busy" @click="download('json')">下载报告 JSON</button><button class="btn primary" :disabled="busy" @click="download('html')"><Download :size="15"/>下载可打印 HTML</button></template><button class="btn secondary" @click="close">关闭报告</button></footer></dialog></Teleport></template>
<style scoped>
.report-dialog{width:min(900px,calc(100vw - 32px));max-height:92dvh;padding:0;border:1px solid var(--border);border-radius:14px;background:var(--paper);color:var(--text)}.report-dialog::backdrop{background:#11182766}.report-dialog header,.report-dialog footer{display:flex;align-items:center;justify-content:space-between;padding:18px 24px;gap:12px;background:var(--paper)}.report-dialog header{border-bottom:1px solid var(--border)}.report-dialog footer{border-top:1px solid var(--border);flex-wrap:wrap;justify-content:flex-end}.report-body{padding:20px 24px;max-height:65dvh;overflow:auto;line-height:1.8;overflow-wrap:anywhere}.report-privacy,.report-summary,.report-message{background:var(--surface);padding:14px;border:1px solid var(--border);border-radius:8px}.report-error{color:var(--danger,#cf3434)}.report-scope{display:grid;grid-template-columns:120px 1fr;gap:8px}.report-scope dd{margin:0}.report-version,.report-feedback{border:1px solid var(--border);border-radius:9px;padding:16px;margin:14px 0}.report-title p,.report-version p,.report-feedback p{margin:8px 0}.report-body h3{margin-top:24px}.report-dimensions{display:flex;gap:14px;flex-wrap:wrap}.report-text{white-space:pre-wrap;overflow-wrap:anywhere}.report-feedback blockquote{margin:12px 0;border-left:2px solid var(--border);padding:8px 12px;color:var(--muted);background:var(--surface)}.report-action{border-top:1px solid var(--border);padding:12px 0}.report-action small{display:block;color:var(--muted)}.report-body summary{cursor:pointer}.report-body ul{padding-left:20px}@media(max-width:600px){.report-dialog header,.report-dialog footer,.report-body{padding:14px 16px}.report-scope{grid-template-columns:80px 1fr}.report-dialog footer .btn{flex:1 1 auto}.report-body{max-height:59dvh}}
</style>
